:root {
  --bg: #1a1c2c;
  --card: #f4f4f4;
  --ink: #1a1c2c;
  --accent: #ff6b6b;
  --accent-dark: #d94f4f;
  --muted: #5a5f7a;
}
* { box-sizing: border-box; }
body {
  margin: 0;
  min-height: 100vh;
  display: grid;
  place-items: center;
  background: var(--bg);
  background-image: linear-gradient(45deg, #22243a 25%, transparent 25%), linear-gradient(-45deg, #22243a 25%, transparent 25%), linear-gradient(45deg, transparent 75%, #22243a 75%), linear-gradient(-45deg, transparent 75%, #22243a 75%);
  background-size: 32px 32px;
  background-position: 0 0, 0 16px, 16px -16px, -16px 0;
  font-family: 'Courier New', monospace;
  font-size: 18px;
  padding: 16px;
}
.card {
  background: var(--card);
  border: 4px solid var(--ink);
  box-shadow: 8px 8px 0 var(--accent);
  padding: 28px 24px;
  width: 100%;
  max-width: 420px;
  text-align: center;
}
h1 {
  margin: 0 0 16px;
  font-size: 1.6rem;
  letter-spacing: 2px;
  color: var(--ink);
}
.question {
  font-size: 1.5rem;
  font-weight: bold;
  margin: 0 0 20px;
  min-height: 2rem;
}
.answers {
  display: flex;
  gap: 12px;
  justify-content: center;
  margin-bottom: 16px;
}
.btn {
  font-family: inherit;
  font-size: 1.1rem;
  font-weight: bold;
  padding: 12px 20px;
  border: 3px solid var(--ink);
  background: #fff;
  color: var(--ink);
  cursor: pointer;
  box-shadow: 4px 4px 0 var(--ink);
  transition: transform 0.05s, box-shadow 0.05s;
}
.btn:hover:not(:disabled) { background: #ffe9e9; }
.btn:focus-visible { outline: 3px solid var(--accent); outline-offset: 2px; }
.btn:active:not(:disabled) { transform: translate(4px, 4px); box-shadow: none; }
.btn:disabled { opacity: 0.55; cursor: not-allowed; box-shadow: none; }
.answer { min-width: 72px; }
.score-line { font-size: 1.1rem; margin: 0 0 20px; color: var(--muted); }
#score { font-weight: bold; color: var(--accent-dark); }
.controls { display: flex; gap: 12px; justify-content: center; }
@media (max-width: 380px) {
  body { font-size: 16px; }
  .card { padding: 20px 16px; }
  .btn { padding: 10px 14px; }
}

const questionEl = document.getElementById('question');
const answerA = document.getElementById('answer-a');
const answerB = document.getElementById('answer-b');
const scoreEl = document.getElementById('score');
const nextBtn = document.getElementById('next');
const restartBtn = document.getElementById('restart');

let score = 0;
let step = 0;
let answered = false;
const questions = [
  { text: '2 + 2 = ?', a: '4', b: '5', correct: 'a' },
  { text: '3 + 3 = ?', a: '5', b: '6', correct: 'b' }
];

function render() {
  const q = questions[step];
  questionEl.textContent = q.text;
  answerA.textContent = q.a;
  answerB.textContent = q.b;
  answerA.disabled = false;
  answerB.disabled = false;
  answered = false;
  nextBtn.disabled = true;
  scoreEl.textContent = String(score);
}

function choose(which) {
  if (answered) return;
  answered = true;
  answerA.disabled = true;
  answerB.disabled = true;
  nextBtn.disabled = false;
  if (which === questions[step].correct) {
    score += 1;
    scoreEl.textContent = String(score);
  }
}

answerA.addEventListener('click', () => choose('a'));
answerB.addEventListener('click', () => choose('b'));

nextBtn.addEventListener('click', () => {
  if (step === 0) {
    step = 1;
    render();
  } else if (step === 1) {
    step = 2;
    questionEl.textContent = 'Finished';
    answerA.disabled = true;
    answerB.disabled = true;
    nextBtn.disabled = true;
  }
});

restartBtn.addEventListener('click', () => {
  score = 0;
  step = 0;
  render();
});

render();
